const input = $input.first().json;
const session_id = typeof input.session_id === 'string' ? input.session_id.trim() : '';
const rawId = input.draft_id;
const draft_id = rawId === undefined || rawId === null || rawId === '' || rawId === 0 || rawId === '0' ? '' : String(rawId).trim();
if (!session_id && !draft_id) throw new Error('Provide a session_id or draft_id');
return [{ json: { session_id, draft_id } }];

const { session_id, draft_id } = $('Validate Lookup').first().json;
const rows = $input.all().map(item => item.json).filter(row => row && row.id != null);
const matches = rows.filter(row => {
  if (draft_id) return String(row.id) === draft_id;
  return String(row.session_id ?? '') === session_id;
});
matches.sort((a, b) => Number(b.id) - Number(a.id));
if (matches.length === 0) {
  const message = draft_id ? `No post found with ID ${draft_id}` : 'No matching posts found for this session';
  return [{ json: { found: false, drafts: [], message } }];
}
return [{
  json: {
    found: true,
    drafts: matches.slice(0, 10).map(row => ({
      draft_id: String(row.id),
      content: row.content,
      status: row.status,
      session_id: row.session_id ?? null,
      scheduled_at: row.scheduled_at ?? null,
      published_at: row.published_at ?? null,
      approved_at: row.approved_at ?? null
    }))
  }
}];
